def path(lang,kind):return ('' if lang=='en' else '/'+lang)+('/academy/virtual-faculty' if kind=='faculty' else '/applied/education-systems')
def sec(title,text):return '<section class="wrap courses-section"><h2>'+E(title)+'</h2><p>'+E(text)+'</p></section>'
for lang,c in copy.items():
 prefix='' if lang=='en' else '/'+lang
 template=(R/(prefix.lstrip('/')+'/' if prefix else '')/'applied.html').read_text()
