  # Use the real repository wordmark asset within the existing component structure.
  h=h.replace('<span></span>','<img src="/voce-wordmark.svg" alt="" width="92" height="28">');f=footer.replace('<span></span>','<img src="/voce-wordmark.svg" alt="" width="92" height="28">')
  title='VOCE Virtual Faculty' if kind=='faculty' else 'VOCE Education Systems'
  headline=c['headline'] if kind=='faculty' else c['systemsTitle'];deck=c['deck'] if kind=='faculty' else c['systemsDeck']
  body='<section class="topic-hero courses-hero"><div class="wrap"><div class="topic-kicker">'+E(title)+'</div><h1 class="topic-title">'+E(headline)+'</h1><p class="topic-deck">'+E(deck)+'</p><p>'+E(c['status'])+'</p></div></section>'
